'use strict';

/**
* Sort a strided array using heapsort according to a provided callback function.
*
* @module @stdlib/blas-ext-base-gsorthp-by
*
* @example
* import gsorthpBy from '@stdlib/blas-ext-base-gsorthp-by';
*
* var x = [ 1.0, -2.0, 3.0, -4.0 ];
*
* function clbk( a, b ) {
*     if ( a < b ) {
*         return -1;
*     }
*     if ( a > b ) {
*         return 1;
*     }
*     return 0;
* }
*
* gsorthpBy( x.length, x, 1, clbk );
* // x => [ -4.0, -2.0, 1.0, 3.0 ]
*
* @example
* import gsorthpBy from '@stdlib/blas-ext-base-gsorthp-by';
*
* var x = [ 1.0, -2.0, 3.0, -4.0 ];
*
* function clbk( a, b ) {
*     if ( a < b ) {
*         return -1;
*     }
*     if ( a > b ) {
*         return 1;
*     }
*     return 0;
* }
*
* gsorthpBy.ndarray( x.length, x, 1, 0, clbk );
* // x => [ -4.0, -2.0, 1.0, 3.0 ]
*/

// MODULES //

import setReadOnly from '@stdlib/utils-define-nonenumerable-read-only-property';
import main from './main.js';
import ndarray from './ndarray.js';


// MAIN //

setReadOnly( main, 'ndarray', ndarray );


// EXPORTS //

export default main;
